import{_ as t,o,c as r,ag as a}from"./chunks/framework.CrXGS008.js";const m=JSON.parse('{"title":"Frameworks et ressources","description":"","frontmatter":{},"headers":[],"relativePath":"fr/bridge/index.md","filePath":"fr/bridge/index.md"}'),s={name:"fr/bridge/index.md"};function n(i,e,d,c,l,u){return o(),r("div",null,[...e[0]||(e[0]=[a(`<h1 id="frameworks-et-ressources" tabindex="-1">Frameworks et ressources <a class="header-anchor" href="#frameworks-et-ressources" aria-label="Permalink to &quot;Frameworks et ressources&quot;">​</a></h1><p>Chaque script Nayretis parle à votre serveur par le bridge de <code>nay_lib</code>. Il détecte votre framework, votre inventaire, votre target et vos notifications à la première utilisation : le même script tourne sur toutes les configurations prises en charge.</p><h2 id="configurations-prises-en-charge" tabindex="-1">Configurations prises en charge <a class="header-anchor" href="#configurations-prises-en-charge" aria-label="Permalink to &quot;Configurations prises en charge&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>Adaptateurs</th><th>Repli</th></tr></thead><tbody><tr><td>Framework</td><td><code>qbox</code> (qbx_core), <code>ox</code> (ox_core), <code>esx</code> (es_extended), <code>qbcore</code> (qb-core), <code>custom</code></td><td>aucun, le script s&#39;arrête avec une erreur</td></tr><tr><td>Inventaire</td><td><code>ox_inventory</code>, <code>qs-inventory</code>, <code>qb-inventory</code></td><td><code>framework</code> (l&#39;inventaire du framework)</td></tr><tr><td>Target</td><td><code>ox_target</code>, <code>qb-target</code></td><td><code>none</code> (invites de touche)</td></tr><tr><td>Notifications</td><td><code>ox_lib</code>, <code>nayretis</code> (seulement si forcé)</td><td><code>framework</code>, puis <code>native</code> (fil GTA)</td></tr></tbody></table><p>La détection suit l&#39;ordre du tableau. Démarrez <code>nay_lib</code> <strong>après</strong> votre framework, votre inventaire et votre target, sinon ils ne peuvent pas être détectés.</p><h2 id="forcer-un-adaptateur" tabindex="-1">Forcer un adaptateur <a class="header-anchor" href="#forcer-un-adaptateur" aria-label="Permalink to &quot;Forcer un adaptateur&quot;">​</a></h2><p>Si la détection choisit la mauvaise ressource, forcez-la dans <code>server.cfg</code> avec <code>setr</code> (le client la lit aussi) :</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>setr nay:framework &quot;esx&quot;</span></span>
<span class="line"><span>setr nay:inventory &quot;ox_inventory&quot;</span></span>
<span class="line"><span>setr nay:target &quot;ox_target&quot;</span></span>
<span class="line"><span>setr nay:notify &quot;native&quot;</span></span></code></pre></div><p>Les valeurs sont les noms d&#39;adaptateurs ci-dessus, ou <code>auto</code> (par défaut). Voir <a href="/fr/nay-lib/convars">Convars</a>.</p><p>Votre framework n&#39;est pas dans la liste ? Écrivez un <a href="/fr/bridge/custom">adaptateur personnalisé</a>.</p><h2 id="limites-connues" tabindex="-1">Limites connues <a class="header-anchor" href="#limites-connues" aria-label="Permalink to &quot;Limites connues&quot;">​</a></h2><ul><li><strong>ox_core</strong> : il n&#39;y a pas d&#39;indicateur de service, le groupe actif compte donc comme métier en service. Le grade le plus haut d&#39;un groupe compte comme patron.</li><li><strong>ox_inventory</strong> (tout framework) : les objets utilisables doivent exister dans <code>ox_inventory/data/items.lua</code>. ox_inventory n&#39;appelle le callback que pour les objets sans <code>consume</code>, <code>client.export</code> ni <code>server.export</code>.</li><li><strong>qb-inventory</strong> : les métadonnées des objets sont ignorées dans les comptes d&#39;objets.</li><li><strong>qs-inventory</strong> : les résultats des ajouts et retraits d&#39;objets ne sont pas documentés. Tout résultat autre que <code>false</code> compte comme un succès.</li><li><strong>ESX</strong> : les notifications utilisent <code>esx_notify</code> s&#39;il est démarré, le fil GTA sinon.</li></ul>`,12)])])}const f=t(s,[["render",n]]);export{m as __pageData,f as default};
